/**
 * Оптимизированная функция для получения live-матчей
 * Использует специальный эндпоинт на бэкенде, который упрощает получение данных
 * Включает защиту от таймаутов и повторные попытки запросов
 */
export const getLiveMatches = async () => {
  try {
    // Определяем часовой пояс пользователя
    const savedTimezone = localStorage.getItem('userTimezone');
    let timezone;

    if (savedTimezone === 'auto' || !savedTimezone) {
      // Автоматическое определение часового пояса
      timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
      console.log(`Используем автоопределенный часовой пояс: ${timezone}`);
    } else {
      // Используем выбранный пользователем часовой пояс
      timezone = savedTimezone;
      console.log(`Используем выбранный пользователем часовой пояс: ${timezone}`);
    }

    // Формируем URL с параметром часового пояса
    const url = `/api/live?timezone=${encodeURIComponent(timezone)}`;
    console.log(`Запрос к оптимизированному API: ${url}`);

    // Создаем контроллер, который позволит отменить запрос при таймауте
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 15000); // 15 секунд на клиенте

    try {
      const response = await fetch(url, { 
        signal: controller.signal,
        // Отключаем кеширование запросов для live-данных
        cache: 'no-store'
      });

      clearTimeout(timeoutId); // Очищаем таймаут после получения ответа

      if (!response.ok) {
        // Если HTTP-статус не в диапазоне 200-299
        const errorData = await response.json().catch(() => ({}));
        throw new Error(
          errorData.message || 
          `Ошибка получения live-матчей: ${response.status} ${response.statusText}`
        );
      }

      const data = await response.json();
      console.log(`Получены данные: ${data.data?.length || 0} live-матчей`);

      return data;
    } catch (fetchError) {
      clearTimeout(timeoutId); // На всякий случай очищаем таймаут

      if (fetchError.name === 'AbortError') {
        console.error('⚠️ Превышено время ожидания запроса live-матчей');
        throw new Error('Превышено время ожидания. Пожалуйста, повторите запрос позже.');
      }

      throw fetchError;
    }
  } catch (error) {
    console.error('❌ Ошибка при запросе live-матчей:', error);
    throw error;
  }
};

/**
 * Версия функции с автоматическими повторными попытками
 * Пытается запросить данные несколько раз, если сервер временно недоступен
 */
export const getLiveMatchesWithRetry = async (maxRetries = 2, retryDelay = 2000) => {
  let lastError;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      // Если это повторная попытка - ждем указанное время
      if (attempt > 0) {
        console.log(`⏱️ Повторная попытка получения live-матчей (${attempt}/${maxRetries})...`);
        await new Promise(resolve => setTimeout(resolve, retryDelay));
      }

      return await getLiveMatches();
    } catch (error) {
      lastError = error;

      // Если это ошибка сервера (5xx) или таймаут - повторяем запрос
      const isRetriableError = 
        error.message?.includes('503') || 
        error.message?.includes('504') ||
        error.message?.includes('timeout') ||
        error.message?.includes('время ожидания') ||
        error.message?.includes('временно недоступ');

      if (!isRetriableError) {
        console.log('❌ Не повторяем запрос - ошибка не является временной:', error.message);
        throw error; // Для остальных ошибок - сразу выбрасываем исключение
      }

      // На последней попытке выбрасываем ошибку
      if (attempt === maxRetries) {
        console.error(`❌ Все попытки исчерпаны (${maxRetries+1}/${maxRetries+1})`);
        throw lastError;
      }
    }
  }

  throw lastError; // Если мы здесь, значит все попытки не удались
};
